    function run(uint depAmt, uint colAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depAmt)); require(depAmt <= 1000000000000000000000000000000);
        require(depAmt > 0 && colAmt > 0);
        require(address(this).balance >= depAmt);
        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Deposit{value: depAmt}(); if (__ESBMC_reverted()) return;
        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeEther = address(c).balance;
        bool reverted;
        c.Collect(colAmt); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
