import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 depAmt, uint256 colAmt) internal {
        depAmt = bound(depAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depAmt > 0 && colAmt > 0);
        vm.assume(address(this).balance >= depAmt);
        try c.SetMinSum(0) {} catch { return; }
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: depAmt}() {} catch { return; }
        uint256 beforeBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        uint beforeEther = address(c).balance;
        bool reverted;
        try c.Collect(colAmt) { reverted = false; } catch { reverted = true; }
        uint256 afterBal;
        try c.balances(address(this)) returns (uint256 __r) { afterBal = __r; } catch { return; }
        uint afterEther = address(c).balance;
        assertTrue(reverted || colAmt > beforeBal || (afterBal == beforeBal - colAmt && afterEther == beforeEther - colAmt));
    }

    function testFuzz_run(uint256 depAmt, uint256 colAmt) public {
        _run(depAmt, colAmt);
